package blockbranch.realistic;

import java.nio.file.*;import java.util.*;
import blockbranch.cubic.*;
import net.minecraft.core.*;import net.minecraft.core.registries.Registries;
import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;
import net.minecraft.world.level.chunk.status.ChunkStatus;
import net.minecraft.world.level.levelgen.structure.*;
import net.minecraft.world.level.levelgen.structure.pieces.*;
import net.minecraft.world.level.levelgen.structure.structures.*;

/** Two explicitly forced native starts: tests old processors, not natural reachability. */
public final class RuinForcedNegativeQualification {
 private record Fixture(boolean warm,ChunkPos pos,StructureStart start,int queued,int fluidTicks){}
 private static final Map<Boolean,BlockPos> shapeProbes=new HashMap<>();
 private static final List<Fixture> fixtures=new ArrayList<>();private static final Set<ChunkPos> forced=new HashSet<>();private static boolean prepared,done;private static int waits;
 public static void register(){net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents.END_SERVER_TICK.register(server->{if(done)return;try{
  var level=server.overworld();var g=(RealisticGenerator)level.getChunkSource().getGenerator();var random=level.getChunkSource().randomState();var context=StructurePieceSerializationContext.fromLevel(level);boolean reopen=Files.exists(Path.of("forced-saved.json"));
  require(g.deepColdRuinDefinition()==0&&g.warmRuinDefinition()==1&&g.coldRuinDefinition()==1,"Actual old97 feature definitions remain unchanged");
  if(!prepared){SparsePostProcessingQualification.check(level);for(boolean warm:new boolean[]{true,false}){
   var holder=level.registryAccess().lookupOrThrow(Registries.STRUCTURE).getOrThrow(warm?BuiltinStructures.OCEAN_RUIN_WARM:BuiltinStructures.OCEAN_RUIN_COLD);StructureStart start=null;ChunkPos pos=null;
   if(reopen){var saved=com.google.gson.JsonParser.parseString(Files.readString(Path.of("forced-saved.json"))).getAsJsonObject().getAsJsonObject(warm?"warm":"cold");pos=new ChunkPos(saved.get("chunkX").getAsInt(),saved.get("chunkZ").getAsInt());var chunk=level.getChunk(pos.x(),pos.z(),ChunkStatus.STRUCTURE_STARTS);start=level.structureManager().getStartForStructure(holder.value(),chunk);require(start!=null&&start.isValid(),"Forced native saved start reload");}
   else{for(int attempt=0;attempt<64&&start==null;attempt++){
    int x=157144+(attempt%8-4)*16,z=-566216+(attempt/8-4)*16+(warm?0:256);var candidate=new ChunkPos(x>>4,z>>4);var pieces=new StructurePiecesBuilder();
    var building=new ArrayList<StructurePiece>();for(String template:warm?new String[]{"warm_4"}:new String[]{"brick_4","cracked_4","mossy_4"})building.add(new OceanRuinPieces.OceanRuinPiece(context.structureTemplateManager(),net.minecraft.resources.Identifier.parse("minecraft:underwater_ruin/"+template),new BlockPos(candidate.getMinBlockX(),90,candidate.getMinBlockZ()),Rotation.NONE,warm||building.isEmpty()?.8f:building.size()==1?.7f:.5f,warm?OceanRuinStructure.Type.WARM:OceanRuinStructure.Type.COLD,false));var box=building.getFirst().getBoundingBox();int floor=warm?g.warmRuins(random).floorFor(box):g.coldRuins(random).floorFor(box);if(floor>=-64||floor==Integer.MIN_VALUE)continue;
    for(int i=0;i<building.size();i++){if(warm)((WarmRuinAccess)building.get(i)).blockbranch$fitRuin(floor,0);else ((ColdRuinAccess)building.get(i)).blockbranch$fitColdRuin(floor,i);}
    pos=candidate;start=new StructureStart(holder.value(),pos,0,new PiecesContainer(building));var chunk=level.getChunk(pos.x(),pos.z(),ChunkStatus.STRUCTURE_STARTS);chunk.setStartForStructure(holder.value(),start);chunk.markUnsaved();
   }require(start!=null,"Bounded forced native footprint fitting "+warm);}
   var box=start.getBoundingBox();int queued=0,ticks=0;var chunks=new ArrayList<ChunkPos>();for(int z=box.minZ()>>4;z<=box.maxZ()>>4;z++)for(int x=box.minX()>>4;x<=box.maxX()>>4;x++)chunks.add(new ChunkPos(x,z));
   if(!reopen)for(var chunkPos:chunks){var references=level.getChunk(chunkPos.x(),chunkPos.z(),ChunkStatus.STRUCTURE_REFERENCES);references.addReferenceForStructure(holder.value(),pos.pack());references.markUnsaved();}
   if(!reopen)for(var chunkPos:chunks){var proto=level.getChunk(chunkPos.x(),chunkPos.z(),ChunkStatus.FEATURES);var q=((SparsePostProcessingAccess)proto).blockbranch$postProcessing(false);if(q!=null){queued+=q.snapshot().length;var saved=net.minecraft.world.level.chunk.storage.SerializableChunkData.copyOf(level,proto).write();require(saved.getIntOr("blockbranch:column_format",0)==3,"Actual forced native pending updates persisted before admission");}}
   for(var chunkPos:chunks){forced.add(chunkPos);level.setChunkForced(chunkPos.x(),chunkPos.z(),true);var full=level.getChunk(chunkPos.x(),chunkPos.z());ticks+=full.getFluidTicks().count();}
   blockbranch.Blockbranch.LOGGER.info("FORCED_NATIVE_QUEUE family={} box={} queued={} fluidTicks={}",warm?"warm":"cold",box,queued,ticks);require(reopen||queued>0,"Actual family native template enqueued sparse updates");fixtures.add(new Fixture(warm,pos,start,queued,ticks));
   // Explicit synthetic neighbor-shape witness beside each forced native family.
   var probeChunk=new ChunkPos(pos.x()+6,pos.z()+6);var at=new BlockPos(probeChunk.getMinBlockX()+8,box.maxY()+12,probeChunk.getMinBlockZ()+8);var proto=level.getChunk(probeChunk.x(),probeChunk.z(),ChunkStatus.FEATURES);var stair=Blocks.STONE_BRICK_STAIRS.defaultBlockState().setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.WATERLOGGED,true).setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.HORIZONTAL_FACING,Direction.NORTH);
   if(!proto.getBlockState(at).is(Blocks.STONE_BRICK_STAIRS)){require(proto instanceof net.minecraft.world.level.chunk.ProtoChunk&&!(proto instanceof net.minecraft.world.level.chunk.ImposterProtoChunk),"Shape witness starts before admission");proto.setBlockState(at,stair,2);proto.setBlockState(at.north(),stair.setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.HORIZONTAL_FACING,Direction.EAST),2);proto.markPosForPostProcessing(at);proto.markPosForPostProcessing(at.north());}
   forced.add(probeChunk);shapeProbes.put(warm,at);level.setChunkForced(probeChunk.x(),probeChunk.z(),true);level.getChunk(probeChunk.x(),probeChunk.z());
  }prepared=true;return;}
  if(forced.stream().anyMatch(p->!level.areEntitiesLoaded(p.pack()))){require(++waits<200,"Forced resident admission");return;}
  for(var p:forced){var q=((SparsePostProcessingAccess)level.getChunk(p.x(),p.z())).blockbranch$postProcessing(false);require(q==null||q.snapshot().length==0,"Actual forced native updates drained after entity admission");}
  var out=new LinkedHashMap<String,Object>();for(var f:fixtures){var box=f.start.getBoundingBox();var chestPositions=new ArrayList<BlockPos>();var archaeology=new ArrayList<BlockPos>();int stableShapes=0;for(int y=box.minY();y<=box.maxY();y++)for(int z=box.minZ();z<=box.maxZ();z++)for(int x=box.minX();x<=box.maxX();x++){var at=new BlockPos(x,y,z);var state=level.getBlockState(at);if(level.getBlockEntity(at) instanceof net.minecraft.world.level.block.entity.ChestBlockEntity){chestPositions.add(at);require(state.getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.WATERLOGGED)&&!state.getFluidState().isEmpty(),"Negative-Y chest is waterlogged native block entity");}if(state.is(f.warm?Blocks.SUSPICIOUS_SAND:Blocks.SUSPICIOUS_GRAVEL))archaeology.add(at);if(state.getBlock() instanceof StairBlock){require(Block.updateFromNeighbourShapes(state,level,at)==state,"Native final stair shape stable after updates");stableShapes++;}}
   require(chestPositions.size()==1&&!archaeology.isEmpty(),"Both native family chest and archaeology paths");if(!f.warm)for(var piece:f.start.getPieces())require(!((ColdRuinAccess)piece).blockbranch$isDeepCold(),"Adopted cold piece uses unchanged shallow definition");
   var ids=level.getEntitiesOfClass(net.minecraft.world.entity.monster.zombie.Drowned.class,new net.minecraft.world.phys.AABB(box.minX()-8,box.minY()-8,box.minZ()-8,box.maxX()+9,box.maxY()+9,box.maxZ()+9)).stream().map(e->e.getUUID().toString()).sorted().toList();var shapeAt=shapeProbes.get(f.warm);var shaped=level.getBlockState(shapeAt);require(shaped.getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.STAIRS_SHAPE)==net.minecraft.world.level.block.state.properties.StairsShape.OUTER_RIGHT&&shaped.getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.WATERLOGGED),"Sparse native neighbor update changes straight waterlogged stairs to outer-right");var shapeChunk=level.getChunkAt(shapeAt);var shapeSave=net.minecraft.world.level.chunk.storage.SerializableChunkData.copyOf(level,shapeChunk).write();var shapeReload=net.minecraft.world.level.chunk.storage.SerializableChunkData.parse(level,level.palettedContainerFactory(),shapeSave).read(level,level.getPoiManager(),new net.minecraft.world.level.chunk.storage.RegionStorageInfo("forced-shape",level.dimension(),"forced-shape"),shapeChunk.getPos());require(shapeReload.getBlockState(shapeAt)==shaped,"Actual changed neighbor shape survives native serialization/read");
   var row=new LinkedHashMap<String,Object>();row.put("forced",true);row.put("syntheticNeighborShapeProbe",shapeAt.toShortString());row.put("syntheticNeighborShapeResult","waterlogged outer_right; native save/read passed");row.put("chunkX",f.pos.x());row.put("chunkZ",f.pos.z());row.put("box",box.toString());row.put("queuedBeforeAdmission",f.queued);int finalFluidTicks=0;for(int z=box.minZ()>>4;z<=box.maxZ()>>4;z++)for(int x=box.minX()>>4;x<=box.maxX()>>4;x++)finalFluidTicks+=level.getChunk(x,z).getFluidTicks().count();row.put("fluidTicksAfterAdmission",finalFluidTicks);row.put("stableStairShapes",stableShapes);row.put("archaeologyRemaining",archaeology.size());row.put("residentIds",ids);row.put("pieceHash",ColdRuinGrounding.hash(f.start.getPieces().stream().map(p->p.createTag(context).toString()).toList().toString()));
   var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)level.getBlockEntity(chestPositions.getFirst());var key=f.warm?"warm":"cold";if(reopen){var saved=com.google.gson.JsonParser.parseString(Files.readString(Path.of("forced-saved.json"))).getAsJsonObject().getAsJsonObject(key);require(ColdRuinGrounding.hash(level,box).equals(saved.get("stateHash").getAsString()),"Forced native exact saved state");require(row.get("pieceHash").equals(saved.get("pieceHash").getAsString()),"Forced native exact piece reload");require(new com.google.gson.Gson().toJson(ids).equals(saved.get("residentIds").toString()),"Forced native resident UUIDs");require(chest.getLootTable()==null,"Consumed forced native chest preserved");}
   else{require(chest.getLootTable()!=null,"Native chest loot preserved");for(var at:archaeology)require(level.getBlockEntity(at) instanceof net.minecraft.world.level.block.entity.BrushableBlockEntity,"Actual native archaeology block entity");for(int i=0;i<chest.getContainerSize();i++)chest.removeItem(i,chest.getItem(i).getCount());chest.setChanged();level.setBlock(archaeology.getFirst(),(f.warm?Blocks.SAND:Blocks.GRAVEL).defaultBlockState(),3);}
   row.put("stateHash",ColdRuinGrounding.hash(level,box));out.put(key,row);
  }
  Files.writeString(Path.of(reopen?"forced-reopen.json":"forced-saved.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));for(var p:forced)level.setChunkForced(p.x(),p.z(),false);server.saveEverything(false,true,true);Files.writeString(Path.of("result.txt"),"PASS");done=true;
 }catch(Throwable t){done=true;blockbranch.Blockbranch.LOGGER.error("FORCED_NEGATIVE_RUIN_FAIL",t);try{Files.writeString(Path.of("result.txt"),"FAIL "+t);}catch(Exception ignored){}}finally{if(done)server.halt(false);}});}
 private static void require(boolean ok,String message){if(!ok)throw new AssertionError(message);}
}
